steps.script:
var mod = System.getModule("com.mbcom.onboarding");

if (!vraHost) throw "Workflow variable vraHost is not set - pick the VCF Automation host in the workflow Variables tab";

if (!projectName || !cloudAccountName) throw "projectName and cloudAccountName are required";

projectId  = mod.getProjectId(vraHost, projectName);
endpointId = mod.getCloudAccountId(vraHost, cloudAccountName);

function p2(n) { return (n < 10 ? "0" : "") + n; }
if (!planName || String(planName).trim() === "") {
    var d = new Date();
    effectivePlanName = "vRO-Onboard-" + d.getFullYear() + p2(d.getMonth() + 1) + p2(d.getDate()) +
        "-" + p2(d.getHours()) + p2(d.getMinutes()) + p2(d.getSeconds());
} else {
    effectivePlanName = String(planName).trim();
}
System.log("Plan name: " + effectivePlanName);

planLink = System.getModule("com.mbcom.onboarding").createOnboardingPlan(
    vraHost, effectivePlanName, projectId, endpointId,
    "vRO onboarding of " + vmNames.length + " VM(s): " + vmNames.join(", ").substring(0, 200));

// Always stamped on every onboarding plan; the onboarded machines inherit them
var cp = new Properties();
cp.put("onboardedStatus", "true");
cp.put("workflowRun", "true");

System.getModule("com.mbcom.onboarding").setPlanCustomProperties(vraHost, planLink, cp);

machines = System.getModule("com.mbcom.onboarding").findUnmanagedMachines(vraHost, planLink, vmNames);

var foundLower = {};
for (var i = 0; i < machines.length; i++) foundLower[String(machines[i].get("name")).toLowerCase()] = true;

missingVms = [];
for (var j = 0; j < vmNames.length; j++) {
    if (!foundLower[String(vmNames[j]).trim().toLowerCase()]) missingVms.push(vmNames[j]);
}

System.log("Found " + machines.length + "/" + vmNames.length + " VM(s) as unmanaged");
if (missingVms.length > 0) {
    System.warn("Missing: " + missingVms.join(", "));
    if (failOnMissing) throw "Aborting: " + missingVms.length + " VM(s) not found as unmanaged: " + missingVms.join(", ");
}
if (machines.length === 0) throw "Nothing to onboard";

var notFound = System.getModule("com.mbcom.onboarding")
    .verifyOnboardedDeployments(vraHost, deploymentNames);

if (notFound.length > 0) {
    System.warn(notFound.length + " deployment(s) not visible yet: " + notFound.join(", "));
    if (planStatus === "OK") planStatus = "OK_WITH_MISSING";
} else {
    System.log("All " + deploymentNames.length + " deployment(s) onboarded and visible.");
}

var mod = System.getModule("com.mbcom.onboarding");
function count(p) { return (p && p.keys) ? p.keys.length : 0; }

if (count(vmCustomProperties) > 0) {
    var ids = [];
    for (var i = 0; i < machines.length; i++) ids.push(String(machines[i].get("link")).replace(/^.*\//, ""));
    mod.setMachineCustomProperties(vraHost, ids, vmCustomProperties);
} else {
    System.log("No VM-level custom properties requested");
}

if (count(deploymentCustomProperties) > 0) {
    for (var j = 0; j < deploymentNames.length; j++) {
        mod.setDeploymentCustomProperties(vraHost, deploymentNames[j], deploymentCustomProperties);
    }
} else {
    System.log("No deployment-level custom properties requested");
}
